{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Ziprasidone, a high-transfer heteroaromatic drug, had an absolute oral bioavailability of 60 ± 23% in healthy subjects in the fed state, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Trazodone, another high-transfer heteroaromatic drug, showed an absolute oral bioavailability of 63% in fasted volunteers, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Urapidil had an oral bioavailability of 78% that was not dependent on food intake, supporting high bioavailability under fed conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Ondansetron, a heteroaromatic drug with a similar small-molecule profile, had an absolute oral bioavailability of 75% after an 8 mg oral dose.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Metolazone is available in an approximately 100% bioavailable oral form in humans, providing an upper-range example of high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "TFMPP showed low oral bioavailability in humans (<1% urinary recovery), but this is due to extensive first-pass metabolism of its basic piperazine, a structural/mechanistic feature not shared by the query's neutral pyrazolone.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a small, neutral pyrazolone (antipyrine-like). Multiple high-transfer human absolute bioavailability measurements in heteroaromatic drugs (ziprasidone 60% fed, trazodone 63%, urapidil 78%, ondansetron 75%, metolazone ~100%) all exceed the 20% threshold. The only low-bioavailability analogue is mechanistically dissimilar (basic piperazine first-pass metabolism), so the evidence strongly supports high oral bioavailability.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule itself in the supplied evidence.",
    "Fed-state-specific data for the query are absent; extrapolation relies on fed-state ziprasidone and food-independent urapidil/ondansetron data.",
    "Low-bioavailability analogues (TFMPP, mCPP, brexanolone) are mechanistically distinct and were not used to support a low prediction."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

